/**
 * Shared sample event — design/design_spec.md 5.2 (data identical to RAW in prototype/index.html).
 * Used by the seating golden test (Ф7a) and by seeds (Ф2, plan 11.5).
 * Generated once from prototype RAW; phones are fictional demo numbers.
 * Family order = data order (f01…f65 as in the prototype); `seq` = index, used as the stable tie-break.
 */
export type SampleRsvp = "yes" | "no" | "pending";

export type SampleFamily = {
  id: string;
  name: string;
  /** Member who added the family: ake (Әкесі), ana (Анасы), jas (Жастар). */
  memberId: "ake" | "ana" | "jas";
  categoryId: string;
  rsvp: SampleRsvp;
  expected: number;
  confirmed: number | null;
  phone: string | null;
  /** Manually locked table (🔒 in 5.2), otherwise null. */
  tableNo: number | null;
  locked: boolean;
  lockedBy: string | null;
  /** null = invitation not sent yet («Жіберілмеді»). */
  sentDaysAgo: number | null;
  seq: number;
};

